# Exact completed native-capture test-artifact cleanup; keep the current Qwen image and objects.
$ErrorActionPreference = 'Stop'
$root = 'C:\public\project-hyle\hyle'
$stage = Join-Path $root '.scratch\architecture-refactor-2026-10-18\d4-windows-preparation-2026-10-21\first-decode-startup-2026-10-21\native-fix'
$plan = Get-Content -LiteralPath (Join-Path $stage 'root-cleanup-plan.json') -Raw | ConvertFrom-Json
$allowed = [IO.Path]::GetFullPath($stage).TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
function Assert-Identity($row) {
  $file = Get-Item -LiteralPath $row.path -ErrorAction Stop
  if ($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Not a regular file: $($row.path)" }
  if ($file.Length -ne $row.bytes -or (Get-FileHash -LiteralPath $row.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw "Identity changed: $($row.path)" }
}
Assert-Identity $plan.evidence
Assert-Identity $plan.archive
foreach ($row in $plan.remove) {
  $full = [IO.Path]::GetFullPath($row.path)
  if (-not $full.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetExtension($full) -notin '.exe','.map','.dll') { throw "Outside exact artifact scope: $full" }
  Assert-Identity $row
}
foreach ($row in $plan.keep) { Assert-Identity $row }
$active = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) })
if ($active.Count) { throw 'A native-fix executable is still running' }
foreach ($row in $plan.remove) { Remove-Item -LiteralPath $row.path -Force }
foreach ($row in $plan.keep) { Assert-Identity $row }
$result = [ordered]@{ completed=$true; exact_plan=$plan; removed=@($plan.remove).Count; logical_bytes=[double]($plan.remove | Measure-Object -Property bytes -Sum).Sum; hardlink_bytes_are_not_physical_reclaim=$true; source_script=[IO.File]::ReadAllText($PSCommandPath) }
$result | ConvertTo-Json -Depth 14 | Set-Content -LiteralPath (Join-Path $root 'docs\evidence\performance\qwen-capture-resource-reuse-2026-10-21.cleanup.json') -Encoding utf8
[pscustomobject]$result | Select-Object completed,removed,logical_bytes | ConvertTo-Json
